138|/**
139| * Sanitize one configured bank value. Full-value environment references of
140| * the form `$VAR` and `${VAR}` are expanded from the plugin process env.
141| * Partial interpolation is intentionally unsupported and remains literal.
142| */
143|export function sanitizeBankValue(
144|  value: unknown,
145|  env: Record<string, string | undefined> = process.env,
146|): string | undefined {
147|  if (typeof value !== 'string') return undefined;
148|  const trimmed = value.trim();
149|  if (!trimmed) return undefined;
150|
151|  const match = trimmed.match(ENV_REF_RE);
152|  if (!match) return trimmed;
153|
154|  const envName = match[1] ?? match[2];
155|  if (!envName) return undefined;
156|  const envValue = env[envName]?.trim();
157|  return envValue || undefined;
