162| * non-string keys/values, strip leading/trailing whitespace, and expand
163| * full-value env refs in values. Returns an empty object when absent or not a
164| * plain object.
165| */
166|export function sanitizeBankMap(
167|  map: unknown,
168|  env: Record<string, string | undefined> = process.env,
169|): Record<string, string> {
170|  if (!map || typeof map !== 'object' || Array.isArray(map)) return {};
171|  const out: Record<string, string> = {};
172|  for (const [key, value] of Object.entries(map)) {
173|    const cleanKey = key.trim();
174|    const cleanValue = sanitizeBankValue(value, env);
175|    if (cleanKey && cleanValue) {
176|      out[cleanKey] = cleanValue;
177|    }
178|  }
179|  return out;
